(() => {
  'use strict';
  const API = 'http://localhost:3000/api';
  const app = document.querySelector('#app');
  const toastEl = document.querySelector('#toast');
  const state = { user:null, csrf:sessionStorage.getItem('pressly.csrf')||'', templates:[], categories:[], reminders:[], view:'dashboard', notes:[], page:1, totalPages:1, query:'', status:'', language:'', note:null, draft:null, priorView:'dashboard', loading:false, authMode:'login', authError:'', resetToken:'' };
  const logoMarkup='<svg viewBox="0 0 32 32" aria-hidden="true" focusable="false"><rect x="5" y="3.5" width="22" height="25" rx="3" fill="none" stroke="currentColor" stroke-width="2"/><path d="M10 11h12M10 16h12M10 21h8" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>';
  const avatarMarkup='<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><circle cx="12" cy="8" r="3.5" fill="none" stroke="currentColor" stroke-width="1.8"/><path d="M5 20c.5-3.6 3.2-5.5 7-5.5s6.5 1.9 7 5.5" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>';
  let reminderPollTimer=null;
  const nav = [
    ['dashboard','▦','Overview'],['create','☑','Generate Press Note'],['history','◴','History'],['templates','◫','Templates'],['categories','⬡','Categories'],['settings','⚙','Settings']
  ];
  nav.splice(3,0,['reminders','clock','Reminders']);
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const statusLabel = s => ({draft:'Draft',in_review:'Awaiting Review',changes_requested:'Changes Requested',approved:'Approved & Finalized'}[s] || s || 'Draft');
  const notify = (msg, bad=false) => { toastEl.textContent=msg; toastEl.className='toast show'; if(bad) toastEl.style.background='#9d3434'; else toastEl.style.background=''; clearTimeout(notify.timer); notify.timer=setTimeout(()=>toastEl.className='toast',3200); };
  async function api(path, options={}) {
    const method=(options.method||'GET').toUpperCase();
    const headers={'Accept':'application/json',...(options.body?{'Content-Type':'application/json'}:{}),...(options.headers||{})};
    if(!['GET','HEAD','OPTIONS'].includes(method) && state.csrf) headers['X-CSRF-Token']=state.csrf;
    let response;
    try { response=await fetch(`${API}${path}`,{...options,method,headers,credentials:'include'}); }
    catch { throw new Error('Could not reach Pressly. Confirm the backend is running at http://localhost:3000 and FRONTEND_ORIGIN matches this page.'); }
    let result={}; try { result=await response.json(); } catch { /* backend returned no JSON */ }
    if(!response.ok){ if(response.status===401){state.user=null;state.csrf='';render();} const error=new Error(result?.error?.message||`Request failed (${response.status}).`); error.code=result?.error?.code; error.status=response.status; error.details=result?.error?.details; throw error; }
    return result;
  }
  const body = value => JSON.stringify(value);
  const statusBadge = status => `<span class="badge ${esc(status)}">${esc(statusLabel(status))}</span>`;
  const pageTitle = (title, sub, action='') => `<header class="page-heading"><div><div class="eyebrow">${esc(sub)}</div><h1>${esc(title)}</h1></div>${action}</header>`;
  const selectedTheme = () => document.documentElement.dataset.theme==='dark'?'dark':'light';
  function themeIcon(theme){return theme==='dark'?'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.2 15.1A8.5 8.5 0 0 1 8.9 3.8 8.7 8.7 0 1 0 20.2 15.1Z" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/></svg>':'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="4" fill="none" stroke="currentColor" stroke-width="1.8"/><path d="M12 2v2m0 16v2M4.93 4.93l1.42 1.42m11.3 11.3 1.42 1.42M2 12h2m16 0h2M4.93 19.07l1.42-1.42m11.3-11.3 1.42-1.42" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>';}
  function shell(content){
    document.documentElement.dataset.theme=localStorage.getItem('pressly.theme')||'light';
    const theme=selectedTheme();
    app.innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="side-logo"><span class="brand-mark">${logoMarkup}</span><span>Pressly<small>STUDIO</small></span></div><nav class="side-nav" aria-label="Main navigation">${nav.map(([id,icon,label])=>`<button class="nav-item ${state.view===id?'active':''}" data-view="${id}">${icon==='clock'?'<img class="nav-icon nav-icon-img" src="assets/clock.png" alt="">':`<span class="nav-icon" aria-hidden="true">${icon}</span>`}<span>${label}</span></button>`).join('')}</nav><div class="side-version">Pressly Editorial <span class="dot"></span></div></aside><section class="app-main"><header class="topbar"><div class="topbar-brand">${logoMarkup}<strong>Pressly</strong></div><div class="topbar-actions"><button type="button" class="btn btn-soft theme-toggle" data-theme-toggle aria-label="Current theme: ${theme}. Switch to ${theme==='dark'?'light':'dark'} mode" title="Current theme: ${theme}; click to switch">${themeIcon(theme)}<span>${theme==='dark'?'Dark mode':'Light mode'}</span></button><button class="profile-menu" data-view="settings" title="Account settings"><span class="profile-avatar">${avatarMarkup}</span><span class="profile-name">${esc(state.user?.fullName||'Account')}</span></button></div></header><main class="main-content">${content}</main></section></div>`;
    addSpeechControls();
  }
  function loginScreen(){
    if(state.view==='password-reset'){
      app.innerHTML=`<main class="auth-layout"><section class="auth-brand"><div class="brand-lockup"><span class="brand-mark">${logoMarkup}</span>Pressly</div><div class="auth-copy"><h1>Reset your password.</h1><p>Request a one-time reset token. It expires after 30 minutes.</p></div></section><section class="auth-panel"><div class="auth-card"><h2>Password reset</h2><p>Enter your account email to request a one-time token.</p>${state.resetToken?`<div class="status-notice">Local development reset token: <code>${esc(state.resetToken)}</code></div><br>`:''}<form id="reset-request-form"><div class="field"><label>Email address</label><input class="input" name="email" type="email" required maxlength="254"></div><button class="btn btn-soft btn-block">Request reset token</button></form><form id="reset-confirm-form" style="margin-top:18px"><div class="field"><label>Reset token</label><input class="input" name="token" required maxlength="128" value="${esc(state.resetToken)}"></div><div class="field"><label>New password - 10 characters minimum</label><input class="input" name="newPassword" type="password" required minlength="10" maxlength="128"></div><button class="btn btn-primary btn-block">Set new password</button></form><div class="auth-switch"><button class="text-button" data-reset-back>Back to sign in</button></div></div></section></main>`;addSpeechControls();return;
    }
    app.innerHTML=`<main class="auth-layout"><section class="auth-brand"><div class="brand-lockup"><span class="brand-mark">${logoMarkup}</span>Pressly</div><div class="auth-copy"><h1>Create Press Notes with AI.</h1><p>Generate, review and finalize professional press notes with ease.</p><div class="engine-pill"><span class="dot"></span> Intelligent PR generation engine ready</div></div><footer class="auth-foot"><span>Pressly · Press Note Studio</span><span>Streamlined press releases</span></footer></section><section class="auth-panel"><div class="auth-card"><h2>${state.authMode==='login'?'Sign In':'Create your account'}</h2><p>${state.authMode==='login'?'Enter your credentials to access your account.':'Register to save and manage your press notes.'}</p>${state.authError?`<div class="error-box" role="alert">${esc(state.authError)}</div><br>`:''}<form id="auth-form">${state.authMode==='register'?`<div class="field"><label for="fullName">Full name</label><input class="input" id="fullName" name="fullName" autocomplete="name" minlength="2" maxlength="120" required></div>`:''}<div class="field"><label for="email">Email Address</label><input class="input" id="email" name="email" type="email" autocomplete="email" maxlength="254" placeholder="name@example.com" required></div><div class="field"><label for="password">Password ${state.authMode==='register'?'<span class="hint">- 10 characters minimum</span>':''}</label><input class="input" id="password" name="password" type="password" autocomplete="${state.authMode==='login'?'current-password':'new-password'}" minlength="${state.authMode==='register'?10:1}" maxlength="128" required></div><button class="btn btn-primary btn-block" type="submit">${state.authMode==='login'?'Sign In':'Create Account'}</button></form>${state.authMode==='login'?`<div class="auth-switch"><button class="text-button" data-reset-open>Forgot password?</button></div>`:''}<div class="auth-switch">${state.authMode==='login'?'New to Pressly?':'Already have an account?'} <button class="text-button" data-auth-mode="${state.authMode==='login'?'register':'login'}">${state.authMode==='login'?'Create an account':'Sign in'}</button></div></div></section></main>`;addSpeechControls();
  }
  async function loadNotes(){
    const q=new URLSearchParams({page:String(state.page),pageSize:'10'}); if(state.query)q.set('q',state.query);if(state.status)q.set('status',state.status);if(state.language)q.set('language',state.language);
    const r=await api(`/press-notes?${q}`);state.notes=r.data.notes||[];state.totalPages=r.meta?.totalPages||1;return r.meta||{};
  }
  function dashboard(){
    const notes=state.notes; const total=state.totalItems??notes.length; const drafts=notes.filter(n=>n.status==='draft'||n.status==='changes_requested').length; const approved=notes.filter(n=>n.status==='approved').length;
    const upcoming=state.reminders.filter(r=>!r.completedAt&&r.eventDate>=new Date().toISOString().slice(0,10)).slice(0,3);
    return `${pageTitle('Dashboard','Editorial Operations',`<button class="btn btn-primary" data-view="create">? Create Press Note</button>`)}<div class="stats-grid"><div class="stat-card"><div><div class="stat-label">Total Notes</div><div class="stat-value">${total}</div></div><span class="stat-icon">?</span></div><div class="stat-card"><div><div class="stat-label">Drafts on this page</div><div class="stat-value">${drafts}<span class="dot" style="margin-left:6px;background:#f0a000"></span></div></div><span class="stat-icon">?</span></div><div class="stat-card"><div><div class="stat-label">Approved on this page</div><div class="stat-value">${approved}<span class="dot" style="margin-left:6px;background:#13a891"></span></div></div><span class="stat-icon">?</span></div></div><section class="panel"><div class="section-title"><span>Upcoming reminders</span><button class="text-button" data-view="reminders">Manage reminders ?</button></div>${upcoming.map(r=>`<div class="version-row"><strong>${esc(r.title)}</strong><span class="muted small">${esc(r.eventDate)} ${r.eventTime?`- ${esc(String(r.eventTime).slice(0,5))}`:''}</span></div>`).join('')||'<div class="empty-state compact">No upcoming reminders.</div>'}</section><section class="panel" style="margin-top:16px"><div class="section-title"><span>Recent Press Notes <span class="badge">${notes.length} shown</span></span><button class="text-button" data-view="history">View All ?</button></div>${notes.length?notesTable(notes,false):`<div class="empty-state"><strong>Your workspace is ready</strong>Create a press note to see it here.</div>`}<div class="pager"><span>Page ${state.page} of ${state.totalPages}</span><div class="pagination-controls"><button class="btn btn-soft" data-page="prev" ${state.page<=1?'disabled':''}>Previous</button><button class="btn btn-soft" data-page="next" ${state.page>=state.totalPages?'disabled':''}>Next</button></div></div></section>`;
  }
  function notesTable(notes, history){return `<div class="table-wrap"><table class="notes-table"><thead><tr><th>Title</th><th>Language</th><th>Last updated</th><th>Status</th><th>Action</th></tr></thead><tbody>${notes.map(n=>`<tr><td><button class="note-title" data-open-note="${n.id}">${esc(n.title)}</button></td><td>${n.language==='hi'?'हिन्दी':'English'}</td><td>${esc(n.updatedAt?new Date(n.updatedAt).toLocaleDateString():'—')}</td><td>${statusBadge(n.status)}</td><td><button class="text-button" data-open-note="${n.id}">${history?'Open':'View'} →</button></td></tr>`).join('')}</tbody></table></div>`;}
  function historyView(){return `${pageTitle('History','Archive & Records')}<div class="toolbar"><input class="input" id="search-notes" type="search" placeholder="Search press notes by title…" value="${esc(state.query)}"><select id="filter-status"><option value="">All statuses</option>${['draft','in_review','changes_requested','approved'].map(s=>`<option value="${s}" ${state.status===s?'selected':''}>${esc(statusLabel(s))}</option>`).join('')}</select><select id="filter-language"><option value="">All languages</option><option value="en" ${state.language==='en'?'selected':''}>English</option><option value="hi" ${state.language==='hi'?'selected':''}>Hindi</option></select></div><section class="panel">${state.notes.length?notesTable(state.notes,true):`<div class="empty-state"><strong>No press notes found</strong>Try changing your filters or create a new note.</div>`}<div class="pager"><span>Page ${state.page} of ${state.totalPages}</span><div class="pagination-controls"><button class="btn btn-soft" data-page="prev" ${state.page<=1?'disabled':''}>Previous</button><button class="btn btn-soft" data-page="next" ${state.page>=state.totalPages?'disabled':''}>Next</button></div></div></section>`;}
  const templateName = key => {const t=state.templates.find(x=>x.templateKey===key);return t?.name?.en||key||'General Event';};
  function templatesView(){return `${pageTitle('Templates','Blueprint Library',`<span class="badge">${state.templates.length} available</span>`)}<p class="muted" style="margin:-15px 0 22px">Each template has its own editorial structure, visual theme, typography and suggested source details.</p><div class="template-grid">${state.templates.map(t=>{const pr=t.presentation||{};return `<article class="template-card theme-${esc(pr.theme||'navy')} format-${esc(pr.format||'classic')}" style="--template-font:${esc(pr.font||'Manrope')}"><div class="template-top"><span class="template-icon">${esc((t.name?.en||'P').slice(0,1))}</span><span class="template-code">${esc(t.templateKey)}</span></div><h3>${esc(t.name?.en||t.templateKey)}</h3><p>${esc(t.description?.en||'')}</p><p class="small template-details"><strong>Helpful details</strong><br>${esc((pr.inputDetails||[]).join(' / '))}</p><button class="btn btn-soft" data-use-template="${esc(t.templateKey)}">Use Template</button></article>`}).join('')}</div>`;}
  function templatePresentation(key){return state.templates.find(t=>t.templateKey===key)?.presentation||{theme:'navy',font:'Manrope',format:'classic'};}
  function templatePaperClass(key){const p=templatePresentation(key);return `theme-${esc(p.theme||'navy')} format-${esc(p.format||'classic')}`;}
  function templateFontStyle(key){return `--template-font:${esc(templatePresentation(key).font||'Manrope')}`;}
  function categoriesView(){return `${pageTitle('Categories','Manage your event categories')}<section class="form-card"><h2>Your categories</h2><p class="muted small">Categories belong to your account and are available while drafting press notes.</p><form id="category-form" class="inline-form"><div class="field"><label for="category-name">New category</label><input class="input" id="category-name" name="name" maxlength="160" required placeholder="e.g. Education"></div><button class="btn btn-primary">Add category</button></form><div class="stack-list">${state.categories.map(c=>`<div class="version-row"><strong>${esc(c.name)}</strong><span><button class="text-button" data-category-edit="${c.id}">Rename</button><button class="text-button danger-text" data-category-delete="${c.id}">Delete</button></span></div>`).join('')||'<div class="empty-state">No categories yet. Add one above.</div>'}</div></section>`;}
  function settingsView(){return `${pageTitle('Settings','Account & Security')}<section class="form-card"><h2>Profile information</h2><form id="profile-form" class="form-grid"><div class="field"><label for="profile-name">Full name</label><input class="input" id="profile-name" name="fullName" required minlength="2" maxlength="120" value="${esc(state.user?.fullName)}"></div><div class="field"><label for="profile-email">Email</label><input class="input" id="profile-email" name="email" type="email" required maxlength="254" value="${esc(state.user?.email)}"></div><button class="btn btn-primary">Save profile</button></form></section><section class="form-card"><h2>Change password</h2><form id="password-change-form" class="form-grid"><div class="field"><label for="current-password">Current password</label><input class="input" id="current-password" name="currentPassword" type="password" autocomplete="current-password" required maxlength="128"></div><div class="field"><label for="new-password">New password (10 characters minimum)</label><input class="input" id="new-password" name="newPassword" type="password" autocomplete="new-password" required minlength="10" maxlength="128"></div><button class="btn btn-primary">Update password</button></form></section><section class="form-card"><h2>Forgot your password?</h2><p class="muted">Use the one-time reset flow. Local development displays the token; production deployments should connect a secure delivery service.</p><button class="btn btn-soft" data-reset-open>Open password reset</button></section><section class="form-card"><h2>Appearance</h2><p class="muted">Theme preference is saved in this browser.</p><button type="button" class="btn btn-soft" data-theme-toggle>${document.documentElement.dataset.theme==='dark'?'Switch to light mode':'Switch to dark mode'}</button></section><section class="form-card"><h2>Session</h2><button class="btn btn-danger" data-logout>Sign Out</button></section>`;}
  function remindersView(){return `${pageTitle('Reminders','Upcoming event reminders')}<section class="form-card"><h2>Add an event reminder</h2><form id="reminder-form" class="form-grid"><div class="field"><label for="reminder-title">Event name</label><input class="input" id="reminder-title" name="title" required maxlength="240"></div><div class="field"><label for="reminder-date">Date</label><input class="input" id="reminder-date" name="eventDate" type="date" min="${new Date().toISOString().slice(0,10)}" required></div><div class="field"><label for="reminder-time">Time (optional)</label><input class="input" id="reminder-time" name="eventTime" type="time"></div><div class="field"><label for="reminder-note">Note (optional)</label><input class="input" id="reminder-note" name="note" maxlength="1000"></div><button class="btn btn-primary">Add reminder</button></form></section><section class="form-card"><h2>Saved reminders</h2>${state.reminders.map(r=>`<div class="reminder-row ${r.completedAt?'completed':''}"><div><strong>${esc(r.title)}</strong><div class="small muted">${esc(r.eventDate)} ${r.eventTime?`- ${esc(String(r.eventTime).slice(0,5))}`:''}${r.note?` - ${esc(r.note)}`:''}</div></div><div><button class="text-button" data-reminder-complete="${r.id}" data-completed="${r.completedAt?'false':'true'}">${r.completedAt?'Reopen':'Complete'}</button><button class="text-button danger-text" data-reminder-delete="${r.id}">Delete</button></div></div>`).join('')||'<div class="empty-state">No reminders saved yet.</div>'}</section>`;}
  function splitLines(text){return text.split(/\r?\n/).map(v=>v.trim()).filter(Boolean);}
  function linesValue(list, get=x=>x){return Array.isArray(list)?list.map(get).filter(Boolean).join('\n'):'';}
  function createView(){
    const d=state.draft||{templateKey:state.templates[0]?.templateKey||'',language:'en',sourceFacts:{eventName:'',category:'',eventDescription:'',eventDate:'',eventTime:'',timeZone:'Asia/Kolkata',venue:'',institutionName:'',organizer:'',participantCount:null,participantCategories:[],activities:[],outcomes:[],speakers:[],approvedQuotes:[],contactInfo:{organizationName:'',email:'',phone:''},additionalInstructions:''},content:null};
    const f=d.sourceFacts||{}; const content=d.content;
    return `${pageTitle(d.noteId?'Edit Press Note':'Create Press Note','Drafting Room')}<div class="stepper" style="margin:-8px 0 18px"><span class="step active"><span class="step-num">1</span> Details</span><span>›</span><span class="step ${content?'active':''}"><span class="step-num">2</span> Generate</span><span>›</span><span class="step ${d.noteId?'active':''}"><span class="step-num">3</span> Review</span></div>${d.noteId?`<div class="status-notice" style="margin-bottom:14px">Editing saved version ${d.currentVersionNumber}. Saving uses the API’s expected version number to prevent overwriting newer changes.</div>`:''}<form id="note-form"><div class="editor-grid"><div><section class="form-card"><h2>▣ &nbsp; Basic Information</h2><div class="form-grid"><div class="field span-2"><label for="eventName">Event or programme name <span class="hint">· required</span></label><input class="input" name="eventName" id="eventName" maxlength="240" value="${esc(f.eventName||'')}" required></div><div class="field"><label for="category">Category</label><input class="input" name="category" id="category" list="category-options" maxlength="160" value="${esc(f.category||'')}" placeholder="e.g. Educational Event"><datalist id="category-options">${state.categories.map(c=>`<option value="${esc(c.name)}"></option>`).join('')}</datalist></div><div class="field"><label for="templateKey">Template <span class="hint">· API supplied</span></label><select name="templateKey" id="templateKey" required>${state.templates.map(t=>`<option value="${esc(t.templateKey)}" ${d.templateKey===t.templateKey?'selected':''}>${esc(t.name?.en||t.templateKey)}</option>`).join('')}</select></div><div class="field"><label for="language">Output language</label><select name="language" id="language"><option value="en" ${d.language==='en'?'selected':''}>English</option><option value="hi" ${d.language==='hi'?'selected':''}>Hindi</option></select></div><div class="field"><label for="speechLanguage">Speech input language</label><select id="speechLanguage" name="speechLanguage"><option value="en-IN" ${(localStorage.getItem('pressly.speechLanguage')|| (d.language==='hi'?'hi-IN':'en-IN'))==='en-IN'?'selected':''}>English (India)</option><option value="en-US" ${localStorage.getItem('pressly.speechLanguage')==='en-US'?'selected':''}>English (US)</option><option value="en-GB" ${localStorage.getItem('pressly.speechLanguage')==='en-GB'?'selected':''}>English (UK)</option><option value="hi-IN" ${(localStorage.getItem('pressly.speechLanguage')|| (d.language==='hi'?'hi-IN':'en-IN'))==='hi-IN'?'selected':''}>Hindi (India)</option></select><span class="hint">Choose the language you will speak; recognition is handled by your browser.</span></div><div class="field"><label for="eventDate">Event date</label><input class="input" name="eventDate" id="eventDate" type="date" value="${esc(f.eventDate||'')}"></div><div class="field"><label for="eventTime">Event time</label><input class="input" name="eventTime" id="eventTime" type="time" value="${esc((f.eventTime||'').slice(0,5))}"></div><div class="field"><label for="timeZone">Time zone</label><input class="input" name="timeZone" id="timeZone" maxlength="80" value="${esc(f.timeZone||'Asia/Kolkata')}" placeholder="Asia/Kolkata"></div><div class="field"><label for="venue">Venue</label><input class="input" name="venue" id="venue" maxlength="240" value="${esc(f.venue||'')}"></div><div class="field"><label for="institutionName">Institution / organization</label><input class="input" name="institutionName" id="institutionName" maxlength="240" value="${esc(f.institutionName||'')}"></div><div class="field"><label for="organizer">Organizer</label><input class="input" name="organizer" id="organizer" maxlength="240" value="${esc(f.organizer||'')}"></div><div class="field"><label for="participantCount">Participant count</label><input class="input" name="participantCount" id="participantCount" type="number" min="0" max="100000000" value="${f.participantCount??''}"></div><div class="field"><label for="participantCategories">Participant categories <span class="hint">· one per line</span></label><textarea name="participantCategories" id="participantCategories">${esc(linesValue(f.participantCategories))}</textarea></div><div class="field span-2"><label for="eventDescription">Event description</label><textarea name="eventDescription" id="eventDescription" maxlength="5000" placeholder="Share the verified background and purpose of the event">${esc(f.eventDescription||'')}</textarea></div><div class="field"><label for="activities">Activities <span class="hint">· one per line</span></label><textarea name="activities" id="activities">${esc(linesValue(f.activities))}</textarea></div><div class="field"><label for="outcomes">Verified outcomes <span class="hint">· one per line</span></label><textarea name="outcomes" id="outcomes">${esc(linesValue(f.outcomes))}</textarea></div><div class="field"><label for="speakers">Speakers <span class="hint">· Name | designation, one per line</span></label><textarea name="speakers" id="speakers">${esc(linesValue(f.speakers,s=>typeof s==='string'?s:[s.name,s.designation].filter(Boolean).join(' | ')))}</textarea></div><div class="field"><label for="approvedQuotes">Approved quotes <span class="hint">· one per line</span></label><textarea name="approvedQuotes" id="approvedQuotes">${esc(linesValue(f.approvedQuotes,q=>typeof q==='string'?q:(q.quote||q.text||'')))}</textarea></div><div class="field span-2"><label for="additionalInstructions">Writing instructions <span class="hint">· optional</span></label><textarea name="additionalInstructions" id="additionalInstructions" maxlength="2000">${esc(f.additionalInstructions||'')}</textarea></div></div></section><section class="form-card"><h2>▧ &nbsp; Organization Contact</h2><p class="muted small">Only supplied details can appear in the generated note.</p><div class="form-grid"><div class="field"><label for="orgName">Organization name</label><input class="input" id="orgName" name="orgName" maxlength="240" value="${esc(f.contactInfo?.organizationName||'')}"></div><div class="field"><label for="contactEmail">Media contact email</label><input class="input" id="contactEmail" name="contactEmail" type="email" maxlength="254" value="${esc(f.contactInfo?.email||'')}"></div><div class="field"><label for="contactPhone">Contact phone</label><input class="input" id="contactPhone" name="contactPhone" maxlength="40" value="${esc(f.contactInfo?.phone||'')}"></div></div></section></div><div><section class="form-card"><h2>✧ &nbsp; Content & Directives</h2><div class="status-notice">AI uses the facts entered here. Verify all names, dates, figures, quotes and contact details before approval.</div><label class="image-toggle"><input type="checkbox" name="includeImage" ${d.includeImage?'checked':''}><span><strong>Generate an event image</strong><small>Ask the AI to create a 16:9 image to accompany this press note.</small></span></label>${content?`<div class="field" style="margin-top:14px"><label for="revisionInstructions">${d.noteId?'Ask AI to revise this saved note':'Revise this candidate'}</label><textarea id="revisionInstructions" maxlength="1000" placeholder="For example: make the tone more concise while preserving all supplied facts."></textarea><button type="button" class="btn btn-soft" data-revise style="margin-top:8px">${d.noteId?'Request AI revision':'Regenerate with instructions'}</button></div>`:''}</section>${content?candidateHtml(content,f):`<section class="form-card"><div class="empty-state"><strong>Your draft will appear here</strong>Enter verified facts, then generate a candidate for review.</div></section>`}</div></div><div class="editor-actions" style="margin-top:15px"><div class="small muted">${d.noteId?`Saved note · version ${d.currentVersionNumber}`:'Candidate generation does not save a note'}</div><div style="display:flex;gap:9px;flex-wrap:wrap"><button type="button" class="btn btn-outline" data-action="back">Cancel</button>${content?`<button type="button" class="btn btn-soft" data-copy>Copy Text</button><button type="submit" class="btn btn-primary">${d.noteId?'Save Changes':'Save Draft'}</button>`:`<button type="button" class="btn btn-primary" data-generate>Generate Press Note →</button>`}</div></div></form>`;
  }
  function contactMarkup(facts){
    const contact=facts?.contactInfo||{};
    const rows=[['Organization',contact.organizationName||facts?.institutionName],['Email',contact.email],['Phone',contact.phone]].filter(([,value])=>value);
    if(!rows.length)return '';
    return `<section class="contact-panel" aria-label="Contact information"><h3>Contact Information</h3>${rows.map(([label,value])=>`<div class="contact-line"><strong>${label}</strong><span>${esc(value)}</span></div>`).join('')}</section>`;
  }
  function imageMarkup(image){return image?.data&&['image/png','image/jpeg','image/webp'].includes(image.mimeType)?`<figure class="press-note-image"><img src="data:${esc(image.mimeType)};base64,${image.data}" alt="AI-generated event illustration"><figcaption>AI-generated event image ? review before publication</figcaption></figure>`:'';}
  function candidateHtml(c,facts){const key=state.draft?.templateKey;return `<article class="paper-card candidate-paper template-paper ${templatePaperClass(key)}" style="${templateFontStyle(key)}" id="candidate"><div class="note-listen"><button class="btn btn-soft" type="button" data-speak-note>Listen to note</button></div><div class="paper-meta"><span>AI generated candidate · requires human review</span>${c.dateline?`<span>${esc(c.dateline)}</span>`:''}</div>${imageMarkup(state.draft?.generatedImage)}<h2 contenteditable="true" data-content="headline">${esc(c.headline||'')}</h2><p contenteditable="true" data-content="openingParagraph">${esc(c.openingParagraph||'')}</p>${(c.bodyParagraphs||[]).map((p,i)=>`<p contenteditable="true" data-content="bodyParagraphs" data-index="${i}">${esc(p)}</p>`).join('')}${c.closingParagraph?`<p contenteditable="true" data-content="closingParagraph">${esc(c.closingParagraph)}</p>`:''}${contactMarkup(facts)}${c.requiresHumanReview?'<p class="review-required">Human review required before approval.</p>':''}</article>`;}
  function paperContent(c,title,facts,templateKey=state.note?.templateKey,image=state.note?.generatedImage){return `<article class="paper-card review-paper template-paper ${templatePaperClass(templateKey)}" style="${templateFontStyle(templateKey)}"><div class="note-listen"><button class="btn btn-soft" type="button" data-speak-note>Listen to note</button></div><div class="paper-meta"><span>FOR IMMEDIATE RELEASE</span>${statusBadge(state.note?.status||'draft')}</div>${imageMarkup(image)}<h2>${esc(c.headline||title)}</h2>${c.dateline?`<p class="small muted">${esc(c.dateline)}</p>`:''}<p>${esc(c.openingParagraph||'')}</p>${(c.bodyParagraphs||[]).map(p=>`<p>${esc(p)}</p>`).join('')}${c.closingParagraph?`<p>${esc(c.closingParagraph)}</p>`:''}${contactMarkup(facts)}${c.requiresHumanReview?'<p class="review-required">Human review required before approval.</p>':''}</article>`;}
  async function openNote(id){const r=await api(`/press-notes/${id}`);state.note=r.data.note;state.priorView=state.view;state.view='detail';render();}
  async function detailView(){
    const n=state.note; const c=n.content||{};let versions=[];try{const r=await api(`/press-notes/${n.id}/versions`);versions=r.data.versions||[]}catch{}
    return `${pageTitle(n.title,'Press Note · Version '+n.currentVersionNumber,`<span>${statusBadge(n.status)}</span>`)}<div class="split-review"><div>${paperContent(c,n.title,n.sourceFacts,n.templateKey)}<div class="editor-actions" style="margin-top:12px"><button class="btn btn-outline" data-copy-note>Copy Text</button><button class="btn btn-outline" data-print>Print</button><button class="btn btn-soft" data-edit-note>Edit Draft</button><button class="btn btn-soft" data-view="history">Back to History</button></div></div><aside class="panel review-side"><h3>Review & status</h3><p class="small muted">Actions are available only for supported status transitions.</p><div style="margin:14px 0">${statusBadge(n.status)}</div>${n.status==='draft'||n.status==='changes_requested'?`<button class="btn btn-primary btn-block" data-transition="submit-review">Submit for Review</button>`:''}${n.status==='in_review'?`<button class="btn btn-primary btn-block" data-transition="approve">Approve Note</button><div class="field" style="margin-top:12px"><label for="change-comment">Request changes</label><textarea id="change-comment" maxlength="1000" placeholder="Describe the changes requested"></textarea><button class="btn btn-danger btn-block" data-transition="request-changes" style="margin-top:8px">Request Changes</button></div>`:''}${n.status==='approved'?`<p class="status-notice">This note is approved. Saving edits revokes approval and returns it to Draft.</p>`:''}<hr style="border:0;border-top:1px solid var(--line);margin:18px 0"><h3>Version history</h3><div>${versions.map(v=>`<div class="version-row" style="padding:11px 0"><span><strong>v${v.versionNumber}</strong><br><span class="muted">${esc(v.actionType)} · ${esc(v.changeSummary||'')}</span></span><button class="text-button" data-version="${v.versionNumber}">View</button></div>`).join('')||'<p class="small muted">No versions found.</p>'}</div></aside></div>`;
  }
  async function versionView(versionNumber){const r=await api(`/press-notes/${state.note.id}/versions/${versionNumber}`);const v=r.data.version;return `${pageTitle(`Version ${v.versionNumber}`,'Immutable Version Snapshot',`<button class="btn btn-soft" data-view="detail">Back to note</button>`)}${paperContent(v.content,v.title,v.sourceFacts,v.templateKey)}<div class="editor-actions" style="margin-top:14px"><span class="small muted">Saved ${esc(v.createdAt?new Date(v.createdAt).toLocaleString():'')}</span><button class="btn btn-primary" data-restore-version="${v.versionNumber}">Restore as New Version</button></div>`;}
  async function render(){
    if(!state.user){loginScreen();return;}
    try {
      let content='';
      if(state.view==='dashboard'||state.view==='history'){const m=await loadNotes();state.totalItems=m.totalItems||0;if(state.view==='dashboard')await loadReminders();content=state.view==='dashboard'?dashboard():historyView();}
      else if(state.view==='create')content=createView();
      else if(state.view==='templates')content=templatesView();
      else if(state.view==='categories')content=categoriesView();
      else if(state.view==='settings')content=settingsView();
      else if(state.view==='reminders'){await loadReminders();content=remindersView();}
      else if(state.view==='detail')content=await detailView();
      else if(state.view==='version')content=await versionView(state.versionNumber);
      else if(state.view==='approved')content=`${pageTitle('Press Note Approved','Editorial Queue')}<div style="max-width:850px;margin:20px auto">${paperContent(state.note.content,state.note.title,state.note.sourceFacts,state.note.templateKey)}<div class="editor-actions" style="margin-top:14px"><button class="btn btn-outline" data-copy-note>Copy Text</button><button class="btn btn-outline" data-print>Print</button><button class="btn btn-primary" data-view="dashboard">Return to Dashboard →</button></div></div>`;
      shell(content);
    } catch(e){ if(state.user){shell(`${pageTitle('Connection issue','Pressly')}<div class="error-box" role="alert">${esc(e.message)}</div><button class="btn btn-primary" data-retry style="margin-top:14px">Try again</button>`);} }
  }
  function parseSpeaker(value){const line=value.trim();const parts=line.split('|').map(x=>x.trim());if(parts.length>1)return {name:parts.shift(),designation:parts.join(' | ')||null};const match=line.match(/^(.*?)\s*\(([^()]*)\)\s*$/);return match?{name:match[1].trim(),designation:match[2].trim()}:{name:line,designation:null};}
  function readForm(form){
    const fd=new FormData(form), val=k=>String(fd.get(k)||'').trim(), num=val('participantCount');
    const contactInfo={organizationName:val('orgName')||null,email:val('contactEmail')||null,phone:val('contactPhone')||null};
    return {templateKey:val('templateKey'),language:val('language'),sourceFacts:{eventName:val('eventName'),category:val('category')||null,eventDescription:val('eventDescription')||null,eventDate:val('eventDate')||null,eventTime:val('eventTime')?`${val('eventTime')}:00`:null,timeZone:val('timeZone')||null,venue:val('venue')||null,institutionName:val('institutionName')||null,organizer:val('organizer')||null,participantCount:num?Number(num):null,participantCategories:splitLines(val('participantCategories')),activities:splitLines(val('activities')),outcomes:splitLines(val('outcomes')),speakers:splitLines(val('speakers')).map(parseSpeaker),approvedQuotes:splitLines(val('approvedQuotes')).map(quote=>({quote})),contactInfo:(contactInfo.organizationName||contactInfo.email||contactInfo.phone)?contactInfo:null,additionalInstructions:val('additionalInstructions')||null}};
  }
  function collectContent(){
    const c=structuredClone(state.draft.content);const nodes=[...document.querySelectorAll('[data-content]')];for(const el of nodes){const key=el.dataset.content; if(key==='bodyParagraphs')c.bodyParagraphs[Number(el.dataset.index)]=el.innerText.trim();else c[key]=el.innerText.trim();}return c;
  }
  async function generate(form){
    if(!form.reportValidity())return;
    state.loading=true;form.classList.add('loading');
    try{const data=readForm(form),includeImage=Boolean(form.elements.includeImage?.checked);state.draft={...state.draft,...data,includeImage};const r=await api('/press-notes/generate',{method:'POST',body:body({...data,includeImage})});state.draft.content=r.data.candidate;if(r.data.generatedImage)state.draft.generatedImage=r.data.generatedImage;notify('Candidate generated. Review it carefully; it has not been saved.');await render();}
    catch(e){form.classList.remove('loading');state.loading=false;notify(e.message,true);}
  }
  async function saveDraft(form){
    if(!form.reportValidity())return;
    const data=readForm(form);state.draft={...state.draft,...data};const content=collectContent();if(!content.headline||!content.openingParagraph||!content.bodyParagraphs?.some(Boolean)){notify('Add a headline, opening paragraph and at least one body paragraph.',true);return;}
    const title=data.sourceFacts.eventName;const payload={...data,title,content,changeSummary:state.draft.noteId?'Edited press note':'Initial saved draft',...(state.draft.generatedImage?{generatedImage:state.draft.generatedImage}:{})};
    try{
      if(state.draft.noteId){payload.expectedVersionNumber=state.draft.currentVersionNumber;const r=await api(`/press-notes/${state.draft.noteId}`,{method:'PATCH',body:body(payload)});notify('Changes saved as a new version.');const savedId=state.draft.noteId;state.draft=null;await openNote(savedId);}
      else{const r=await api('/press-notes',{method:'POST',body:body(payload)});const saved=await api(`/press-notes/${r.data.note.id}`);state.note=saved.data.note;state.draft=null;notify('Draft saved. Human review is still required.');state.view='detail';await render();}
    }catch(e){notify(e.message+(e.code==='VERSION_CONFLICT'?' Refresh the note before saving again.':''),true);}
  }
  async function authSubmit(form){const fd=new FormData(form);const fields=Object.fromEntries(fd.entries());state.authError='';try{const path=state.authMode==='login'?'/auth/login':'/auth/register';const r=await api(path,{method:'POST',body:body(fields)});state.user=r.data.user;state.csrf=r.data.csrfToken||'';if(state.csrf)sessionStorage.setItem('pressly.csrf',state.csrf);state.view='dashboard';state.page=1;await Promise.all([loadTemplates(),loadCategories(),loadReminders()]);startReminderChecks();notify(state.authMode==='login'?'Welcome back.':'Account created. Welcome to Pressly.');await render();}catch(e){state.authError=e.message;render();}}
  async function loadTemplates(){const r=await api('/templates');state.templates=r.data.templates||[];}
  async function loadCategories(){const r=await api('/categories');state.categories=r.data.categories||[];}
  function reminderStorageKey(){return `pressly.reminders.notified.${state.user?.id||state.user?.email||'account'}`;}
  function reminderDateTime(reminder){if(!reminder.eventDate||!reminder.eventTime)return null;const d=String(reminder.eventDate).slice(0,10).split('-').map(Number);const t=String(reminder.eventTime).slice(0,5).split(':').map(Number);if(d.length!==3||t.length!==2||d.some(Number.isNaN)||t.some(Number.isNaN))return null;return new Date(d[0],d[1]-1,d[2],t[0],t[1],0,0);}
  function checkDueReminders(){if(!state.user)return;const key=reminderStorageKey();let fired=[];try{fired=JSON.parse(localStorage.getItem(key)||'[]');}catch{}const firedSet=new Set(fired.map(String));const now=Date.now();for(const reminder of state.reminders){if(reminder.completedAt||firedSet.has(String(reminder.id)))continue;const due=reminderDateTime(reminder);if(!due||due.getTime()>now||now-due.getTime()>30*60*1000)continue;firedSet.add(String(reminder.id));try{if('Notification'in window&&Notification.permission==='granted'){const n=new Notification(`Pressly reminder: ${reminder.title}`,{body:reminder.note||`Your event is scheduled for ${String(reminder.eventTime).slice(0,5)}.` ,tag:`pressly-reminder-${reminder.id}`});n.onclick=()=>{window.focus();state.view='reminders';render();n.close();};}else{notify(`Reminder: ${reminder.title}`);}}catch{notify(`Reminder: ${reminder.title}`);} }
    try{localStorage.setItem(key,JSON.stringify([...firedSet]));}catch{}
  }
  function startReminderChecks(){if(reminderPollTimer)clearInterval(reminderPollTimer);checkDueReminders();reminderPollTimer=setInterval(async()=>{if(!state.user)return;try{const r=await api('/reminders');state.reminders=r.data.reminders||[];checkDueReminders();}catch{}},20000);}
  async function loadReminders(){const r=await api('/reminders');state.reminders=r.data.reminders||[];checkDueReminders();}
  async function bootstrap(){
    try{const r=await api('/auth/me');state.user=r.data.user;state.csrf=r.data.csrfToken||state.csrf;if(state.csrf)sessionStorage.setItem('pressly.csrf',state.csrf);if(!state.csrf){state.user=null;state.authError='Please sign in again to refresh this browser tab’s security token.';}await Promise.all([loadTemplates(),loadCategories(),loadReminders()]);if(state.user)startReminderChecks();await render();}
    catch(e){if(e.status!==401){state.authError=`Backend unavailable: ${e.message}`;}try{await loadTemplates();}catch{}loginScreen();}
  }
  async function transition(action){
    const payload={};if(action==='request-changes'){payload.comment=document.querySelector('#change-comment')?.value.trim()||'';if(!payload.comment){notify('Add a comment describing the requested changes.',true);return;}}
    if(state.note?.currentVersionNumber)payload.expectedVersionNumber=state.note.currentVersionNumber;
    try{const r=await api(`/press-notes/${state.note.id}/${action}`,{method:'POST',body:body(payload)});if(action==='approve'){state.note.status='approved';state.note.approvedAt=r.data.approvedAt;state.view='approved';notify('Approved. The note remains on your account and is not published automatically.');}else{state.note.status=r.data.status;notify(action==='submit-review'?'Submitted for review.':'Changes requested.');}await render();}catch(e){notify(e.message,true);}
  }
  function notePlain(c,facts){const contact=facts?.contactInfo||{};const details=[['Organization',contact.organizationName||facts?.institutionName],['Email',contact.email],['Phone',contact.phone]].filter(([,value])=>value).map(([label,value])=>`${label}: ${value}`);return [c.headline,c.dateline,c.openingParagraph,...(c.bodyParagraphs||[]),c.closingParagraph,...details].filter(Boolean).join('\n\n');}
  async function copyText(text){try{await navigator.clipboard.writeText(text);notify('Copied to clipboard.');}catch{notify('Clipboard access is unavailable in this browser.',true);}}
  function addSpeechControls(){
    document.querySelectorAll('#app input[type="text"],#app input[type="email"],#app input[type="search"],#app textarea').forEach((field,index)=>{
      if(field.closest('[contenteditable="true"]')||field.dataset.noSpeech||field.parentElement.querySelector('.speech-input-button'))return;
      if(!field.id)field.id=`speech-field-${index}`;
      const button=document.createElement('button');button.type='button';button.className='speech-input-button';button.dataset.speechTarget=field.id;button.textContent='🎙 Dictate';button.setAttribute('aria-label','Start dictation for '+(field.labels?.[0]?.textContent||'this field'));
      const caption=document.createElement('div');caption.className='speech-caption';caption.id=`${field.id}-caption`;caption.hidden=true;caption.setAttribute('aria-live','polite');caption.setAttribute('aria-atomic','true');caption.innerHTML='<strong>Live captions</strong><span>Start dictation to see recognized words here.</span>';button.setAttribute('aria-describedby',caption.id);
      field.insertAdjacentElement('afterend',button);button.insertAdjacentElement('afterend',caption);
    });
  }
  function dictate(targetId,button){
    const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;
    if(!Recognition){notify('Speech input is not supported in this browser. Try the latest Chrome or Edge.',true);return;}
    if(window.presslyRecognition){const active=window.presslyRecognition;if(active.button===button){active.shouldContinue=false;try{active.recognition.stop();}catch{}return;}active.shouldContinue=false;try{active.recognition.stop();}catch{}window.presslyRecognition=null;}
    const field=document.getElementById(targetId);if(!field)return;
    const caption=document.getElementById(`${targetId}-caption`);const recognition=new Recognition();const control={recognition,button,shouldContinue:true,base:field.value.trim(),finalText:'',finalized:new Set(),retryCount:0,stoppedWithError:false};window.presslyRecognition=control;
    const speechLanguage=document.querySelector('#speechLanguage')?.value||localStorage.getItem('pressly.speechLanguage')||(document.querySelector('#language')?.value==='hi'?'hi-IN':'en-IN');
    recognition.lang=speechLanguage;recognition.maxAlternatives=4;recognition.interimResults=true;recognition.continuous=true;button.textContent='■ Stop dictation';button.setAttribute('aria-label','Stop dictation');if(caption){caption.hidden=false;caption.innerHTML='<strong>Listening</strong><span>Speak now. Captions appear as your words are recognized.</span>';}
    recognition.onresult=event=>{control.retryCount=0;let interimParts=[];let added=[];let lowConfidence=false;for(let i=0;i<event.results.length;i++){const result=event.results[i];const choices=Array.from({length:result.length},(_,index)=>result[index]).map(choice=>({text:String(choice.transcript||'').trim(),confidence:Number(choice.confidence)||0})).filter(choice=>choice.text);const best=choices.reduce((winner,choice)=>choice.confidence>winner.confidence?choice:winner,choices[0]);if(!best)continue;if(result.isFinal){if(!control.finalized.has(i)){added.push(best.text);control.finalized.add(i);if(best.confidence>0&&best.confidence<0.45)lowConfidence=true;}}else interimParts.push(best.text);}if(added.length){control.finalText+=`${control.finalText?' ':''}${added.join(' ').trim()}`;field.value=`${control.base}${control.base&&control.finalText?' ':''}${control.finalText}`;field.dispatchEvent(new Event('input',{bubbles:true}));}if(caption){caption.innerHTML=`<strong>${lowConfidence?'Low confidence ? check the transcript':control.finalText?'Recognized':'Listening'}</strong><span>${esc([control.finalText,interimParts.join(' ').trim()].filter(Boolean).join(' '))||'Speak now?'}</span>`;}};
    recognition.onerror=event=>{if(event.error==='network'){control.retryCount++;if(caption)caption.innerHTML=`<strong>${control.retryCount<3?'Connection issue ? retrying':'Speech service unavailable'}</strong><span>${control.retryCount<3?'Trying to reconnect to your browser speech service?':'Check your internet connection, then click Dictate to try again.'}</span>`;if(control.retryCount>=3){control.shouldContinue=false;control.stoppedWithError=true;notify('Speech recognition could not connect. Check your internet connection and try Dictate again.',true);}return;}const fatal=['not-allowed','service-not-allowed','audio-capture'].includes(event.error);if(caption)caption.innerHTML=`<strong>Dictation ${fatal?'stopped':'paused'}</strong><span>${event.error==='not-allowed'||event.error==='service-not-allowed'?'Allow microphone access in your browser and try again.':event.error==='audio-capture'?'No microphone was detected. Check your microphone connection.':event.error==='no-speech'?'No speech detected yet. Keep speaking or stop dictation.':'Check microphone permission and try again.'}</span>`;if(fatal){control.shouldContinue=false;control.stoppedWithError=true;notify(event.error==='audio-capture'?'Speech recognition stopped. Check your microphone and try again.':'Microphone permission is blocked. Allow it in the browser address bar, then try again.',true);}};
    recognition.onend=()=>{if(control.shouldContinue&&window.presslyRecognition===control){control.finalized.clear();const delay=control.retryCount?Math.min(700*2**(control.retryCount-1),2800):450;setTimeout(()=>{if(control.shouldContinue&&window.presslyRecognition===control){try{recognition.start();}catch{control.shouldContinue=false;control.stoppedWithError=true;if(caption)caption.innerHTML='<strong>Dictation paused</strong><span>Speech recognition could not restart. Click Dictate to try again.</span>';finishSpeechControl(control,caption);}}},delay);return;}finishSpeechControl(control,caption);};
    try{recognition.start();}catch{control.shouldContinue=false;finishSpeechControl(control,caption);notify('Speech input could not start. Check microphone permission and try again.',true);}
  }
  function finishSpeechControl(control,caption){control.button.textContent='?? Dictate';control.button.setAttribute('aria-label','Start dictation');if(caption&&!control.finalText&&!control.stoppedWithError)caption.innerHTML='<strong>Live captions</strong><span>Start dictation to see recognized words here.</span>';if(window.presslyRecognition===control)window.presslyRecognition=null;}
  function speakNote(){
    if(!('speechSynthesis' in window)){notify('Speech playback is not supported in this browser.',true);return;}
    if(window.speechSynthesis.speaking){window.speechSynthesis.cancel();return;}
    const content=state.draft?.content?collectContent():state.note?.content;const facts=state.draft?.sourceFacts||state.note?.sourceFacts;if(!content)return;
    const utterance=new SpeechSynthesisUtterance(notePlain(content,facts));utterance.lang=(state.draft?.language||state.note?.language)==='hi'?'hi-IN':'en-IN';window.speechSynthesis.speak(utterance);
  }
  document.addEventListener('click',async e=>{
    const b=e.target.closest('button');if(!b)return;
    if(b.hasAttribute('data-theme-toggle')){const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;localStorage.setItem('pressly.theme',theme);await render();return;}
    if(b.dataset.speechTarget){dictate(b.dataset.speechTarget,b);return;}
    if(b.hasAttribute('data-speak-note')){speakNote();b.textContent=window.speechSynthesis?.speaking?'Listen to note':'Stop listening';return;}
    if(b.hasAttribute('data-reset-open')){state.view='password-reset';state.resetToken='';loginScreen();return;}
    if(b.hasAttribute('data-reset-back')){state.view='login';loginScreen();return;}
    if(b.dataset.categoryEdit){const category=state.categories.find(c=>String(c.id)===b.dataset.categoryEdit);const name=prompt('Rename category',category?.name||'');if(name?.trim()){try{await api(`/categories/${b.dataset.categoryEdit}`,{method:'PATCH',body:body({name:name.trim()})});await loadCategories();notify('Category renamed.');await render();}catch(err){notify(err.message,true);}}return;}
    if(b.dataset.categoryDelete){if(!confirm('Delete this category?'))return;try{await api(`/categories/${b.dataset.categoryDelete}`,{method:'DELETE'});await loadCategories();notify('Category deleted.');await render();}catch(err){notify(err.message,true);}return;}
    if(b.dataset.reminderComplete){try{await api(`/reminders/${b.dataset.reminderComplete}`,{method:'PATCH',body:body({completed:b.dataset.completed==='true'})});await loadReminders();await render();}catch(err){notify(err.message,true);}return;}
    if(b.dataset.reminderDelete){try{await api(`/reminders/${b.dataset.reminderDelete}`,{method:'DELETE'});await loadReminders();await render();notify('Reminder deleted.');}catch(err){notify(err.message,true);}return;}
    if(b.dataset.authMode){state.authMode=b.dataset.authMode;state.authError='';loginScreen();return;}
    if(b.dataset.view){state.view=b.dataset.view;if(state.view==='create'&&!state.draft)state.draft=null;await render();return;}
    if(b.hasAttribute('data-logout')){try{await api('/auth/logout',{method:'POST'});}catch{}if(reminderPollTimer)clearInterval(reminderPollTimer);reminderPollTimer=null;state.user=null;state.csrf='';sessionStorage.removeItem('pressly.csrf');state.note=null;state.draft=null;state.authMode='login';notify('You have signed out.');render();return;}
    if(b.dataset.openNote){try{await openNote(b.dataset.openNote);}catch(err){notify(err.message,true);}return;}
    if(b.hasAttribute('data-edit-note')){const n=state.note;state.priorView='detail';state.draft={noteId:n.id,currentVersionNumber:n.currentVersionNumber,templateKey:n.templateKey,language:n.language,sourceFacts:n.sourceFacts,content:n.content,generatedImage:n.generatedImage||null};state.view='create';await render();return;}
    if(b.dataset.useTemplate){state.draft={templateKey:b.dataset.useTemplate,language:'en',sourceFacts:{eventName:'',category:'',eventDescription:'',eventDate:'',eventTime:'',timeZone:'Asia/Kolkata',venue:'',institutionName:'',organizer:'',participantCount:null,participantCategories:[],activities:[],outcomes:[],speakers:[],approvedQuotes:[],contactInfo:null,additionalInstructions:''},content:null};state.view='create';render();return;}
    if(b.dataset.page){state.page+=b.dataset.page==='next'?1:-1;await render();return;}
    if(b.hasAttribute('data-generate')){const form=document.querySelector('#note-form');await generate(form);return;}
    if(b.hasAttribute('data-revise')){
      const instructions=document.querySelector('#revisionInstructions')?.value.trim();
      if(!instructions){notify('Enter instructions for the revision.',true);return;}
      const form=document.querySelector('#note-form');
      if(!form.reportValidity())return;
      const data=readForm(form);
      try{
        let candidate;
        if(state.draft?.noteId){
          const includeImage=Boolean(form.elements.includeImage?.checked);state.draft.includeImage=includeImage;const result=await api(`/press-notes/${state.draft.noteId}/revise`,{method:'POST',body:body({instructions,language:data.language,includeImage})});candidate=result.data.candidate;if(result.data.generatedImage)state.draft.generatedImage=result.data.generatedImage;
          candidate=result.data.candidate;
        }else{
          const existing=data.sourceFacts.additionalInstructions||'';
          const revised=[existing,`Revision request: ${instructions}`].filter(Boolean).join('\n\n');
          if(revised.length>2000){notify('Shorten the writing instructions or revision request to fit the 2,000 character limit.',true);return;}
          data.sourceFacts.additionalInstructions=revised||null;
          const includeImage=Boolean(form.elements.includeImage?.checked);state.draft.includeImage=includeImage;const result=await api('/press-notes/generate',{method:'POST',body:body({...data,includeImage})});candidate=result.data.candidate;if(result.data.generatedImage)state.draft.generatedImage=result.data.generatedImage;
          candidate=result.data.candidate;
        }
        state.draft={...state.draft,...data,content:candidate};
        notify(state.draft.noteId?'Revision ready. Save it to create a new version.':'New candidate generated from your facts. It has not been saved.');
        await render();
      }catch(err){notify(err.message,true);}
      return;
    }
    if(b.hasAttribute('data-copy')){const c=collectContent();await copyText(notePlain(c,state.draft.sourceFacts));return;}
    if(b.hasAttribute('data-copy-note')){await copyText(notePlain(state.note.content,state.note.sourceFacts));return;}
    if(b.hasAttribute('data-print')){window.print();return;}
    if(b.dataset.transition){await transition(b.dataset.transition);return;}
    if(b.dataset.version){state.versionNumber=b.dataset.version;state.view='version';await render();return;}
    if(b.dataset.restoreVersion){const n=state.note;try{const r=await api(`/press-notes/${n.id}/versions/${b.dataset.restoreVersion}/restore`,{method:'POST',body:body({expectedVersionNumber:n.currentVersionNumber})});notify('Earlier content restored as a new draft version.');await openNote(n.id);}catch(err){notify(err.message,true);}return;}
    if(b.hasAttribute('data-retry')){await render();return;}
    if(b.dataset.action==='back'){state.draft=null;state.view=state.priorView||'dashboard';await render();}
  });
  document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;const values=Object.fromEntries(new FormData(form).entries());try{
    if(form.id==='auth-form'){await authSubmit(form);return;}
    if(form.id==='note-form'&&state.draft?.content){await saveDraft(form);return;}
    if(form.id==='category-form'){await api('/categories',{method:'POST',body:body({name:values.name})});await loadCategories();notify('Category added.');await render();return;}
    if(form.id==='password-change-form'){await api('/auth/password-reset',{method:'POST',body:body(values)});form.reset();notify('Password updated.');return;}
    if(form.id==='profile-form'){const r=await api('/auth/profile',{method:'PATCH',body:body({fullName:values.fullName,email:values.email})});state.user=r.data.user;notify('Profile updated.');await render();return;}
    if(form.id==='reminder-form'){if(values.eventTime&&'Notification'in window&&Notification.permission==='default'){try{await Notification.requestPermission();}catch{}}await api('/reminders',{method:'POST',body:body(values)});await loadReminders();notify(values.eventTime&&(!('Notification'in window)||Notification.permission!=='granted')?'Reminder saved. Keep Pressly open to receive its in-app alert.':'Reminder saved.');await render();return;}
    if(form.id==='reset-request-form'){const r=await api('/auth/password-reset/request',{method:'POST',body:body(values)});state.resetToken=r.data.resetToken||'';notify(r.data.resetToken?'Reset token created.':'If the account exists, a reset token has been created.');loginScreen();return;}
    if(form.id==='reset-confirm-form'){await api('/auth/password-reset/confirm',{method:'POST',body:body(values)});state.resetToken='';state.view='login';state.authMode='login';state.authError='Password updated. Sign in with your new password.';notify('Password reset complete.');loginScreen();return;}
  }catch(err){notify(err.message,true);}});
  document.addEventListener('input',e=>{if(e.target.id==='search-notes'){clearTimeout(render.searchTimer);state.query=e.target.value;state.page=1;render.searchTimer=setTimeout(render,350);}});
  document.addEventListener('change',async e=>{if(e.target.id==='speechLanguage')localStorage.setItem('pressly.speechLanguage',e.target.value);if(e.target.id==='filter-status'){state.status=e.target.value;state.page=1;await render();}if(e.target.id==='filter-language'){state.language=e.target.value;state.page=1;await render();}});
  bootstrap();
})();
